const PROMPT_CACHE: Record<string, string> = {}

function decodePrompt(key: string, base64: string): string {
	if (!PROMPT_CACHE[key]) {
		PROMPT_CACHE[key] = Buffer.from(base64, "base64").toString("utf8")
	}
	return PROMPT_CACHE[key]
}

