const EXECUTE_INSTRUCTIONS_PREFIX = "EXECUTE ACCORDING TO THE FOLLOWING INSTRUCTIONS!!!"

export function getCodexOfficialInstructions(
	modelName: string,
	systemPrompt: string,
): {
	hasOfficialInstructions: boolean
	instructions: string
} {
	const normalized = (modelName || "").toLowerCase()
	let official = ""
	if (normalized.includes("codex-max")) {
		official = decodePrompt("gpt5_1_codex_max", BASE64_GPT51CODEXMAX)
	} else if (normalized.includes("5.2-codex")) {
		official = decodePrompt("gpt5_2_codex", BASE64_GPT52CODEX)
	} else if (normalized.includes("codex")) {
		official = decodePrompt("gpt5_codex", BASE64_GPT5CODEX)
	} else if (normalized.includes("5.1")) {
		official = decodePrompt("gpt5_1", BASE64_GPT51)
	} else if (normalized.includes("5.2")) {
		official = decodePrompt("gpt5_2", BASE64_GPT52)
	} else {
		official = decodePrompt("default", BASE64_DEFAULT)
	}
	const hasOfficialInstructions = official !== "" && (systemPrompt || "").startsWith(official)
	return { hasOfficialInstructions, instructions: official }
}

export function prependCodexSystemPrompt(input: any[], systemPrompt: string): any[] {
	if (!systemPrompt || input.length === 0) {
		return input
	}
	const firstText = input[0]?.content?.[0]?.text
	if (firstText === EXECUTE_INSTRUCTIONS_PREFIX) {
		return input
	}
	return [
		{
			type: "message",
			role: "user",
			content: [
				{ type: "input_text", text: EXECUTE_INSTRUCTIONS_PREFIX },
				{ type: "input_text", text: systemPrompt },
			],
		},
		...input,
	]
}
